inline BasicObject* Parser_Base_eigenclass::m_parse(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* string = array_at(args, 0);
  BasicObject* file = (args->data.size() > 1) ? args->data[1] : ((new String("(string)", 8)));
  BasicObject* line = (args->data.size() > 2) ? args->data[2] : ((new Integer(1LL)));
  Proc* _block = block;
  BasicObject* parser = nil_instance();
  BasicObject* source_buffer = nil_instance();
  parser = this->m_default_parser((new Array({})), nullptr, nullptr);
  source_buffer = this->m_setup_source_buffer((new Array({file, line, string, parser->m_default_encoding((new Array({})), nullptr, nullptr)})), nullptr, nullptr);
  return parser->m_parse((new Array({source_buffer})), nullptr, nullptr);
  return nil_instance();
}

