struct MainObject : Object {
  const char* ruby_class_name() const override { return "MainObject"; }

  virtual BasicObject* m_run_benchmark(Array* args, Hash* kwargs = nullptr, Proc* block = nullptr) {
    BasicObject* __anon_rest__ = args;  // *rest = whole args
    Proc* _block = block;
    Proc* __anon_block__ = block;
    return nil_instance();
    return nil_instance();
  }

  void __top_level__() {
    BasicObject* source = (new String("1 + 2", 5));
    BasicObject* parser = (new Parser_Ruby40());
    parser->m_diagnostics((new Array({})), nullptr, nullptr)->m_consumer_set((new Array({nil_instance()})), nullptr, nullptr);
    parser->m_diagnostics((new Array({})), nullptr, nullptr)->m_all_errors_are_fatal_set((new Array({false_instance()})), nullptr, nullptr);
    BasicObject* buf = (new Parser_Source_Buffer(static_cast<BasicObject*>((new String("(stdin)", 7)))));
    BasicObject* ast = parser->m_parse((new Array({buf})), nullptr, nullptr);
    if (truthy(ast)) {
      (ruby_puts(ast->m_to_sexp((new Array({})), nullptr, nullptr)), nil_instance());
    }
  }
};

